#!/usr/bin/env python3
"""Regenerates stonerift/docs/RULES.md from the card data. Run: python3 stonerift/tools/gen_rules_doc.py"""
import json, pathlib
root = pathlib.Path(__file__).resolve().parent.parent
data = root / "core" / "StoneRift.Core" / "Data"
C = json.loads((data / "cards.json").read_text(encoding="utf-8"))
D = json.loads((data / "decks.json").read_text(encoding="utf-8"))
fac = {"Magma": "🔥 ماجما", "Tide": "🌊 تيار", "Volt": "⚡ برق", "Crystal": "💎 بلور", "Gravity": "🌀 جاذبية", "None": "محايد"}
typ = {"Creature": "كائن", "Technique": "تقنية", "Trap": "فخ", "Field": "ساحة"}
rows = []
for t in ["Creature", "Technique", "Trap", "Field"]:
    for c in sorted((c for c in C if c["Type"] == t), key=lambda c: (c["Cost"], c["Id"])):
        st = f"{c['Attack']} / {c['Defense']}" if t == "Creature" else ""
        rows.append(f"| **{c['NameAr']}** | {typ[t]} | {fac[c['Faction']]} | {c['Cost']} | {st} | {c['TextAr']} | `{c['Id']}` |")
names = {c["Id"]: c["NameAr"] for c in C}
decks = [f"- **{d['NameAr']}** (`{d['Id']}`): " + ", ".join(f"{names[k]} ×{v}" for k, v in d["Cards"].items()) for d in D]
HEAD = '# قواعد ستون ريفت (StoneRift)\n\n> الملف ده بيتولّد من `core/StoneRift.Core/Data/*.json`. عدّل الكروت هناك، والقيم هنا مجرد نسخة للقراءة.\n\n## العالم\nلما الأرض اتشققت، طلعت من الصدوع بلورات بتنبض بطاقة. كل بلورة شايلة **بصمة** حدث مرّ على الأرض من ملايين السنين: حرارة، أو ضغط، أو برق، أو مية، أو جاذبية. ولما البصمة تتشحن، بتتشكّل **كائن** مصنوع من العنصر بتاعها.\nالكائنات دي مش أرواح ومش كائنات حية. هي قوة خام، و**المُشغّلين** هما اللي بيقرروا يستخدموها إزاي. والمبارزة مش حرب، لكن اختبار لمين فيهم بيفهم كائناته أكتر.\n\n## الفصائل\n| الفصيل | الطابع |\n|---|---|\n| 🔥 الماجما | هجوم مباشر وضرر زيادة |\n| 🌊 التيار | تجميد وتحكم |\n| ⚡ البرق | سرعة: كائنات تهاجم أول ما تنزل |\n| 💎 البلور | دفاع وحماية وفخاخ |\n| 🌀 الجاذبية | قوة تقيلة وكائنات صعب تتلمس |\n\n## الفكرة\nكل لاعب معاه ديك 30 كارت. الهدف إنك تنزّل نقاط حياة الخصم من **4000** لـ **صفر**.\n\n## الدور\n1. **بداية الدور:** طاقتك القصوى تزيد 1 (لحد 10) وتتملي. بعدين تسحب كارت.\n   اللي بيبدأ الماتش مبيسحبش في أول دور، ومحدش يقدر يهاجم في أول دور في الماتش.\n2. **اللعب:** تنزّل كروت بتكلفتها من الطاقة، بأي ترتيب.\n3. **المعركة:** كل كائن في وضع الهجوم يقدر يهاجم مرة واحدة.\n4. **إنهاء الدور.**\n\n## الحلبة\n- **3 خانات كائنات** و**3 خانات فخاخ** لكل لاعب.\n- **كارت ساحة واحد للحلبة كلها:** بيأثّر على كائنات الاتنين، وأي كارت ساحة جديد بيشيل القديم.\n\n## الكائنات\n- تنزل في **وضع الهجوم** أو **وضع الدفاع**.\n- الكائن الجديد مبيهاجمش في نفس الدور، إلا لو كان **سريع**.\n- تقدر تغيّر وضع الكائن مرة في الدور، بس مش بعد ما يهاجم.\n- الكائن اللي في وضع الدفاع مبيهاجمش.\n\n## حساب المعركة\n| الحالة | النتيجة |\n|---|---|\n| هجوم ضد هجوم، المهاجم أقوى | المدافع يتدمّر، وصاحبه يخسر الفرق |\n| هجوم ضد هجوم، المهاجم أضعف | المهاجم يتدمّر، وصاحبه يخسر الفرق |\n| هجوم ضد هجوم، متساويين | الاتنين يتدمّروا، ومحدش يخسر حياة |\n| هجوم ضد دفاع، الهجوم أكبر | المدافع يتدمّر، ومحدش يخسر حياة |\n| هجوم ضد دفاع، الهجوم أصغر | صاحب المهاجم يخسر الفرق |\n| هجوم مباشر | مسموح بس لو الخصم مفيش عنده كائنات ينفع تتهاجم |\n\n## التقنيات والفخاخ\n- **التقنيات** بتتستخدم من إيدك في دورك وتأثيرها فوري.\n- **الفخاخ** بتتحط مقلوبة وبتدفع تكلفتها وقت ما تحطها. بتشتغل **لوحدها** لما الخصم يهاجم، أول فخ مناسب بس في كل هجمة.\n\n## حالات خاصة\n- **إيد مليانة (8 كروت):** الكارت المسحوب بيتفكك على طول.\n- **الديك خلص:** كل مرة تحاول تسحب تخسر 500 نقطة.\n- **التجميد:** الكائن المتجمد مبيهاجمش ومبيغيّرش وضعه لحد آخر دور صاحبه الجاي.\n\n## الأوامر الصوتية\nالصيغة: **[اسم الكائن] + [الأمر] + [الهدف]**\n- «يا ماجرون، اهجم على حارس المرايا»\n- «يا ماجرون، تحول إلى وضعية الدفاع»\n- «انهي الدور»\n\nلو في كائن واحد بس يقدر يهاجم، أو هدف واحد بس، تقدر تقول «اهجم» بس. وفيه أسماء مختصرة لكل كائن (موجودة في `Aliases`).\n'
doc = (HEAD + f"\n## الكروت ({len(C)} كارت)\n| الاسم | النوع | الفصيل | التكلفة | هجوم / دفاع | القدرة | المعرّف |\n|---|---|---|---|---|---|---|\n"
       + "\n".join(rows) + "\n\n## الديكات المبدئية\n" + "\n".join(decks) + "\n")
(root / "docs" / "RULES.md").write_text(doc, encoding="utf-8")
print("Wrote", root / "docs" / "RULES.md")
